def main():
 cp('candidate_registry_native.csv','load_candidate_registry_frozen.csv'); cp('simulation_manifest_native.csv','physical_atlas_manifest.csv'); cp('fd_candidate_operators.parquet','fd_operators.parquet'); cp('tangent_candidate_operators.parquet','tangent_operators.parquet'); cp('fd_derivative_convergence.csv','fd_derivative_convergence.csv'); cp('tangent_vs_fd.csv','tangent_vs_fd.csv'); cp('nonlinear_10pct_vs_fd.csv','nonlinear_10pct_vs_fd.csv'); cp('bus7_amplitude_revalidation.csv','bus7_amplitude_validation.csv');
 # Explicitly empty/blocked outputs: downstream inference is forbidden until tangent validation.
